    float row = 0.0f;
    do {
        float column = 0.0f;
        do {
            int row_index = (int)row;
            int column_index = (int)column;
            unsigned char flip = active_flip;
            int cell_index = row_index + column_index * GRID_COLUMN_COUNT;
            float next_column;
            float right_y;
